import createClient from "openapi-fetch";
import type { paths, components } from "./schema";

export type Order = components["schemas"]["Order"];

const api = createClient<paths>({ baseUrl: "https://api.example.com" });

export async function loadOrder(orderId: string): Promise<Order> {
  const { data, response } = await api.GET("/orders/{orderId}", {
    params: { path: { orderId } },
  });
  if (!response.ok || !data) {
    throw new Error(`GET /orders/${orderId} failed with ${response.status}`);
  }
  return data;
}

function paymentLabel(payment: Order["payment"]): string {
  // The discriminator narrows the union: last4 exists only on card payments.
  return payment.method === "card" ? `Card ending ${payment.last4}` : `Bank ${payment.iban}`;
}
